ALTER TABLE "lesson_media" ADD CONSTRAINT "lesson_media_target_check" CHECK (("lesson_media"."kind" = 'image' and "lesson_media"."slot" is not null and "lesson_media"."slide_key" is null) or ("lesson_media"."kind" = 'audio' and "lesson_media"."slide_key" is not null and "lesson_media"."slot" is null));